# -*- coding: utf-8 -*-
"""탭 2~5 : 각 원리를 단계별로 자세히 설명하는 카드(gen_principle.py 가 불러 쓴다)"""
def card(title, intro, stages, table=None, notes=None):
    h='  <div class="card">\n    <div class="h3">🔎 %s <span class="badge b-high">원리 자세히</span></div>\n    <p class="muted">%s</p>\n    <div class="steps">\n'%(title,intro)
    for t,x in stages: h+='      <div class="step"><b>%s</b> — %s</div>\n'%(t,x)
    h+='    </div>\n'
    if table:
        h+='    <div class="tblwrap" style="max-height:none"><table class="tbl" style="min-width:560px"><thead><tr>'+''.join('<th%s>%s</th>'%(' style="text-align:left"' if i==0 else '',c) for i,c in enumerate(table[0]))+'</tr></thead><tbody>'
        for r in table[1:]: h+='<tr>'+''.join('<td%s>%s</td>'%(' style="text-align:left"' if i==0 else '',c) for i,c in enumerate(r))+'</tr>'
        h+='</tbody></table></div>\n'
    if notes: h+='    <p class="tiny">%s</p>\n'%notes
    return h+'  </div>'

def extend(C):
    C[2]['extra']=card('정수압은 어떻게 만들어지나 — 유체 기둥의 무게에서 모든 방향의 압력까지',
      '정지한 액체 속 한 점의 압력이 왜 깊이에 비례하는지 단계별로 따라가 봅니다.',
      [('① 유체 기둥을 떠올리기','수면에서 깊이 $h$ 까지 단면적 $A$ 인 가상의 기둥을 생각합니다. 기둥 속 액체의 부피는 $Ah$, 질량은 $\\rho Ah$, 무게는 $\\rho Ahg$ 입니다.'),
       ('② 기둥을 받치는 힘','기둥은 정지해 있으므로 알짜 힘이 0 입니다. 기둥의 밑면이 아래쪽 액체에서 받는 위쪽 힘 $pA$ 가 (기둥의 무게 + 수면에 작용하는 대기의 힘 $p_0A$)와 같아야 합니다.'),
       ('③ 압력의 식','$pA=p_0A+\\rho Ahg$ → $p=p_0+\\rho gh$. 깊이가 2 배면 $\\rho gh$ 도 2 배입니다. 그림 3 의 직선입니다.'),
       ('④ 왜 모든 방향인가','액체가 정지하려면 한 점 둘레의 아주 작은 부피에서도 힘이 평형이어야 합니다. 어느 방향의 면에서도 압력이 같지 않으면 액체가 흐릅니다. 그래서 정지한 유체의 한 점에서 압력은 방향과 무관합니다(스칼라).'),
       ('⑤ 왜 모양과 무관한가','용기가 옆으로 퍼져 있어도 같은 깊이의 같은 높이 수평면에서 압력은 같아야 합니다(그렇지 않으면 수평 방향으로 흐름이 생기므로). 그래서 U자관 양쪽의 수면 높이가 같아지고, 파스칼의 역설이 성립합니다.'),
       ('⑥ 압력계와 측정','압력계는 게이지 압력(대기압 기준)을 읽습니다. 수은 기압계는 $p_0=\\rho_{Hg}gh$ 에서 $h\\approx760$ mm. 물 기둥이면 약 10.3 m — 우물에서 펌프가 물을 끌어올릴 수 있는 한계입니다.'),
       ('⑦ 한계','비압축성 · 균일한 밀도 · 정지 상태를 가정했습니다. 흐르는 유체(베르누이) · 큰 깊이에서의 압축 · 가속하는 용기에서는 식이 바뀝니다.')],
      [['단계','물리 법칙','핵심 식','결과'],['기둥의 무게','$W=\\rho Ahg$','$\\rho,g,h$','압력의 원인'],['힘의 평형','$\\sum F=0$','$pA=p_0A+W$','$p=p_0+\\rho gh$'],['모든 방향','국소 평형','스칼라 압력','방향 무관'],['수평면 동압','흐름이 없음','같은 깊이 = 같은 압력','모양 무관']],
      notes='물 10 m = 1 기압 = 약 101 kPa 는 암기하기 좋은 값입니다(정확히 10.3 m).')
    C[3]['extra']=card('유압 장치는 어떻게 작동하나 — 압력 전달 · 면적비 · 일 보존',
      '유압 잭 · 브레이크 · 굴착기 팔의 공통 구조를 단계별로 이해합니다.',
      [('① 밀폐된 유체','실린더 · 호스 · 피스톤으로 닫힌 계에 오일(작동유)이나 물을 채웁니다. 액체는 거의 압축되지 않아($\\kappa\\sim5\\times10^{-10}$ Pa⁻¹) 부피가 일정하게 유지됩니다.'),
       ('② 압력의 생성','작은 피스톤(단면 $A_1$)에 힘 $F_1$ 을 주면 접촉한 액체의 압력이 $P=F_1/A_1$ 만큼 올라갑니다. 이 압력 상승은 정지한 액체 어디에서나 같은 크기입니다(파스칼).'),
       ('③ 큰 피스톤의 힘','같은 압력이 큰 단면 $A_2$ 에 작용하므로 힘은 $F_2=PA_2=F_1A_2/A_1$. 면적비 20 이면 힘이 20 배입니다.'),
       ('④ 대가 : 거리','액체의 부피가 보존되어 $A_1d_1=A_2d_2$. 힘이 20 배가 되면 큰 피스톤은 20 분의 1 만 움직입니다. 일 $F_1d_1=F_2d_2$ 로 같습니다.'),
       ('⑤ 반복 동작(펌프 + 밸브)','한 번 누르는 거리가 작으므로 유압 잭은 체크밸브와 펌프로 여러 번 반복해 눌러 큰 피스톤을 조금씩 올립니다. 작동유가 역류하지 않도록 밸브가 막아 줍니다.'),
       ('⑥ 손실과 효율','씰 마찰 · 누유 · 호스 저항 · 공기 혼입으로 실제 $F_2$ 는 이상값보다 작아 효율이 80 ~ 95 % 입니다. 공기가 섞이면 압축되어 반응이 무뎌집니다(브레이크 에어 빼기).'),
       ('⑦ 응용','자동차 마스터 실린더 → 휠 실린더(브레이크 4 바퀴에 같은 압력), 굴착기 · 지게차 · 리프트 · 프레스. 안전을 위해 릴리프 밸브가 과압을 막습니다.')],
      [['단계','물리 법칙','핵심 식','영향'],['압력 생성','압력 $=F/A$','$P=F_1/A_1$','유체 전체의 압력'],['압력 전달','파스칼의 원리','$P$ 모든 곳 동일','큰 단면 힘'],['힘 증폭','$F=PA$','$F_2=F_1A_2/A_1$','힘 ↑'],['거리 보존','부피 보존','$A_1d_1=A_2d_2$','거리 ↓ (일 일정)']],
      notes='고압 유압 장치는 위험합니다(누유 시 오일 분출). 교실에서는 물 · 주사기 같은 낮은 압력의 안전한 장치만 쓰세요.')
    C[4]['extra']=card('부력은 왜 생기나 — 압력 차이에서 아르키메데스의 원리까지',
      '부력의 크기가 밀어낸 유체의 무게와 같은 까닭을 두 가지 방법으로 확인합니다.',
      [('① 직육면체 물체로 생각하기','밑면적 $A$ · 높이 $\\ell$ 인 물체가 윗면 깊이 $h$ 에 잠겨 있습니다. 윗면은 아래로 $(p_0+\\rho gh)A$, 아랫면은 위로 $(p_0+\\rho g(h+\\ell))A$ 의 힘을 받습니다.'),
       ('② 위 · 아래 힘의 차이','알짜 위로 향한 힘 $=\\rho g\\ell A=\\rho Vg$ ($V=A\\ell$). 대기압 부분은 서로 상쇄됩니다. 옆면의 힘은 같은 깊이에서 서로 반대라 상쇄됩니다.'),
       ('③ 밀어낸 유체의 무게','$\\rho Vg$ 는 물체가 차지한 부피의 액체가 가졌을 무게입니다. 그 부분의 액체는 정지해 있었으므로 주위 액체가 정확히 그만큼의 힘으로 떠받치고 있었습니다 — 물체로 바꿔도 같은 힘이 작용합니다.'),
       ('④ 어떤 모양에서도','압력 분포는 물체의 재질과 무관하게 유체가 정합니다. 따라서 어떤 모양이든 $B=\\rho_fV_{잠긴}g$ 입니다(아르키메데스의 원리).'),
       ('⑤ 뜨기와 가라앉기','무게 $W=\\rho_oVg$ 와 부력 $B=\\rho_fVg$ 를 비교합니다. $\\rho_o<\\rho_f$ → 뜬다(평형은 $B=W$ 에서 잠긴 부피 $V_{잠긴}=V\\rho_o/\\rho_f$) · $\\rho_o>\\rho_f$ → 가라앉는다 · 같으면 중성 부력.'),
       ('⑥ 겉보기 무게 · 밀도 측정','가라앉은 물체를 저울에 매달면 $W_{app}=W-B$. 공기 중 $m$ 과 물속 $m_2$ 로 $\\rho_o=\\rho_w m/(m-m_2)$ — 왕관의 순도를 부피로 비교한 이야기의 원리입니다(6번 탭).'),
       ('⑦ 공기 속의 부력 · 한계','공기에서도 $B=\\rho_{공기}Vg$ (헬륨 풍선 · 열기구). 유체가 가속하는 계, 표면 장력이 중요한 작은 물체, 물체 표면에 붙은 기포가 있는 경우는 보정이 필요합니다.')],
      [['단계','물리 법칙','핵심 식','결과'],['압력 차이','정수압','$\\Delta p=\\rho g\\ell$','위로 향한 알짜 힘'],['힘 계산','$F=pA$','$B=\\rho_fVg$','부력의 크기'],['평형 비교','$B$ 대 $W$','$\\rho_o$ 대 $\\rho_f$','뜸 · 잠김'],['겉보기 무게','$W-B$','$(\\rho_o-\\rho_f)Vg$','밀도 측정']],
      notes='“왕관 이야기”(아르키메데스가 목욕 중 부피를 깨달았다는 일화)는 후대의 기록으로 세부는 확실하지 않으며, 부력의 원리 자체는 분명합니다.')
    C[5]['extra']=card('배는 어떻게 뜨고 안정을 유지하나 — 흘수 · 무게중심 · 부력중심 · 메타센터',
      '뜨는 조건과 기울어졌을 때 되돌아오는 조건을 나누어 따라가 봅니다.',
      [('① 뜨는 조건(평균 밀도)','배 + 짐 + 속 빈 공간 전체의 평균 밀도 $\\bar\\rho=m/V_{전체}$ 가 물보다 작으면 뜹니다. 쇠로 속이 빈 큰 그릇을 만들면 $V_{전체}$ 가 커져 평균 밀도가 작아집니다.'),
       ('② 흘수 계산','$m=\\rho_fV_{잠긴}=\\rho_fLBd$ → $d=m/(\\rho_fLB)$. 짐을 실을수록 $d$ 가 커지고 건현 $H-d$ 가 줄며, $d>H$ 면 물이 들어와 침몰합니다.'),
       ('③ 무게중심 G 와 부력중심 B','무게 $W$ 는 G 에, 부력 $B$ 는 잠긴 모양의 부피 중심 B 에 작용합니다. 똑바로 떠 있을 때 두 힘은 같은 수직선 위에서 크기가 같고 방향이 반대입니다.'),
       ('④ 기울면 B 가 이동','기울어지면 잠긴 모양이 바뀌어 B 가 낮은 쪽(잠긴 쪽)으로 이동합니다. 부력의 작용선과 선체 중심선이 만나는 점이 메타센터 M 입니다.'),
       ('⑤ 복원 돌림힘','M 이 G 보다 위에 있으면 ($GM>0$) 부력과 무게가 만드는 짝힘이 배를 바로 세우는 방향입니다 — 안정. M 이 G 보다 아래이면 ($GM<0$) 더 기울이는 방향 — 불안정(전복).'),
       ('⑥ GM 의 계산','$GM=KB+BM-KG$ — $KB=d/2$, $BM=B^2/(12d)$(직육면체 배). 짐을 높이 실어 $KG$ 가 커지면 GM 이 작아집니다. 폭 $B$ 가 넓으면 $BM$ 이 커져 안정합니다.'),
       ('⑦ 만재흘수선 · 한계','과적을 막는 최대 흘수 표시(담수 · 해수 · 계절별). 작은 각도 근사 · 자유 표면(탱크 속 액체) 효과 · 파도 · 바람은 이 모형에서 제외했습니다.')],
      [['단계','물리 법칙','핵심 식','영향'],['뜨는 조건','$B=W$','$d=m/(\\rho LB)$','흘수 · 건현'],['기울기','돌림힘 평형','G, B 의 이동','복원력'],['안정 판정','메타센터 높이','$GM=KB+BM-KG$','GM>0 안정'],['과적 방지','안전 기준','만재흘수선','침몰 방지']],
      notes='실제 선박의 안정성은 큰 각도까지 복원력 곡선 GZ(θ)로 평가하며, 국제 규정(IMO)이 최소 기준을 정합니다.')
    C[6]['extra']=card('측정의 신뢰도 — 부력식 밀도 측정의 오차를 단계로 따져 보기',
      '실제 실험에서 값이 어긋나는 원인을 분류하고 줄이는 방법을 정리합니다.',
      [('① 직접 측정과 간접 측정','저울이 직접 읽는 것은 $m$ 과 $m_2$ 뿐이고, 밀도 $\\rho$ 는 계산으로 구하는 간접 측정입니다. 간접 측정의 오차는 직접 측정의 오차가 식을 통해 전파된 것입니다.'),
       ('② 우연 오차','저울 눈금 · 손의 떨림 · 물결 때문에 값이 흩어집니다. 같은 측정을 $N$ 번 하면 평균의 불확도는 $\\sigma/\\sqrt N$ 로 줄어듭니다.'),
       ('③ 계통 오차','기포가 붙으면 부력이 커 보이고, 실이 물에 잠기면 질량이 더해지며, 물의 온도를 무시하면 밀도가 틀어집니다. 평균해도 줄지 않으므로 원인을 찾아 보정하거나 제거해야 합니다.'),
       ('④ 오차의 증폭','$m-m_2=\\rho_wV$ 가 작으면(작은 시료) 상대 오차가 $1/V$ 로 커집니다. 큰 시료를 쓰거나 정밀 저울을 씁니다.'),
       ('⑤ 온도 보정','물의 밀도는 4 ℃ 에서 최대(약 1000)이고 20 ℃ 998.2, 80 ℃ 971.8 kg/m³. 온도를 재어 $\\rho_w(T)$ 로 계산합니다.'),
       ('⑥ 안전 수칙','뜨거운 물 · 유리 기구 · 젖은 바닥 · 전기 기구(저울)와 물 접촉에 주의하고, 압력이 높은 장치는 교실에서 쓰지 않습니다. 호스 · 주사기는 연결부를 점검합니다.'),
       ('⑦ 결과의 표현','측정값은 평균 ± 불확도와 단위를 함께 쓰고, 참값(표 값)과의 차이가 불확도 안인지 비교합니다. 안 맞으면 계통 오차를 의심합니다.')],
      [['오차 종류','원인 예','줄이는 방법','평균의 효과'],['우연 오차','눈금 읽기 · 흔들림','반복 측정 · 평균','줄어든다'],['계통 오차','기포 · 온도 · 실 무게','보정 · 개선','줄지 않는다'],['증폭','작은 부피 · 작은 차이','큰 시료 · 정밀 저울','부분적']],
      notes='안전 : 이 자료의 모든 실험은 물과 저울 · 주사기를 쓰는 안전한 실험입니다.')
